import { Semaphore } from 'async-mutex';

const slots = new Semaphore(8);

await slots.runExclusive(async () => {
  await fetchWithRetry(url);       // released when the promise settles
});

const state = new Int32Array(new SharedArrayBuffer(4));
state[0] = 8;                          // permits

function acquire(): void {
  for (;;) {
    const n = Atomics.load(state, 0);
    if (n > 0 && Atomics.compareExchange(state, 0, n, n - 1) === n) return;
    Atomics.wait(state, 0, 0);         // parks until release notifies
  }
}
